import {renderDucking} from './audio-ducking.js';
export const dspDefaults={delay:{time:.2,feedback:.25,wet:.3},reverb:{seconds:.8,decay:3,wet:.25},lowpass:{frequency:1200,q:.7},highpass:{frequency:120,q:.7},distortion:{drive:2,wet:.5}};
const ranges={time:[.001,5],feedback:[0,.95],wet:[0,1],seconds:[.01,10],decay:[.1,10],frequency:[10,22000],q:[.0001,100],drive:[.01,100]};
export function validDSP(buses){const byId=new Map(buses.map(b=>[b.id,b])),edges=new Map();for(const bus of buses){if(bus.effects!==undefined&&(!Array.isArray(bus.effects)||bus.effects.length>32||bus.effects.some(e=>!dspDefaults[e?.type]||typeof e.enabled!=='boolean'||Object.keys(dspDefaults[e.type]).some(k=>!Number.isFinite(e[k])||e[k]<ranges[k][0]||e[k]>ranges[k][1]))))return false;if(bus.sends!==undefined&&(!Array.isArray(bus.sends)||bus.sends.length>32||bus.sends.some(s=>!byId.has(s?.bus)||s.bus===bus.id||!Number.isFinite(s.level)||s.level< -80||s.level>0||typeof s.preFader!=='boolean')))return false;edges.set(bus.id,[bus.parent,...(bus.sends||[]).map(s=>s.bus)].filter(Boolean));}const visiting=new Set(),done=new Set(),visit=id=>{if(visiting.has(id))return false;if(done.has(id))return true;visiting.add(id);for(const target of edges.get(id)||[])if(!visit(target))return false;visiting.delete(id);done.add(id);return true;};return buses.every(b=>visit(b.id));}
export function createDSP(context,data){const input=context.createGain(),output=context.createGain(),nodes=[input,output],own=n=>(nodes.push(n),n);let tail=input;
  for(const effect of data||[]){if(!effect.enabled)continue;let processor,entry,exit;
    if(effect.type==='lowpass'||effect.type==='highpass'){processor=own(context.createBiquadFilter());processor.type=effect.type;processor.frequency.value=effect.frequency;processor.Q.value=effect.q;entry=exit=processor;}
    else if(effect.type==='delay'){processor=own(context.createDelay(5));processor.delayTime.value=effect.time;const feedback=own(context.createGain());feedback.gain.value=effect.feedback;processor.connect(feedback);feedback.connect(processor);entry=exit=processor;}
    else if(effect.type==='reverb'){processor=own(context.createConvolver());const frames=Math.ceil(context.sampleRate*effect.seconds),buffer=context.createBuffer(2,frames,context.sampleRate);let seed=1;for(let c=0;c<2;c++){const values=buffer.getChannelData(c);for(let i=0;i<frames;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;values[i]=(seed/2147483648-1)*Math.pow(1-i/frames,effect.decay);}}processor.buffer=buffer;entry=exit=processor;}
    else{processor=own(context.createWaveShaper());const curve=new Float32Array(4096);for(let i=0;i<curve.length;i++){const x=i/(curve.length-1)*2-1;curve[i]=Math.tanh(x*effect.drive)/Math.tanh(effect.drive);}processor.curve=curve;processor.oversample='2x';entry=exit=processor;}
    if(effect.wet!==undefined){const dry=own(context.createGain()),wet=own(context.createGain()),join=own(context.createGain());dry.gain.value=1-effect.wet;wet.gain.value=effect.wet;tail.connect(dry);dry.connect(join);tail.connect(entry);exit.connect(wet);wet.connect(join);tail=join;}else{tail.connect(entry);tail=exit;}}
  tail.connect(output);return {input,output,dispose(){for(const node of nodes){node.disconnect();if('buffer' in node)node.buffer=null;}nodes.length=0;}};
}
export function renderMixerDSP(editor,bus){const document=editor.element.ownerDocument,section=document.createElement('section');section.className='mixer-dsp';const title=document.createElement('h3');title.textContent='DSP 체인';section.append(title);const button=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=e=>{e.stopPropagation();editor.stopPreview();editor.edit(d=>fn(d.buses.find(b=>b.id===bus.id)));};return b;};
  for(const [index,effect] of (bus.effects||[]).entries()){const row=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=(index+1)+' · '+effect.type;row.append(legend);for(const key of ['enabled',...Object.keys(dspDefaults[effect.type])]){const label=document.createElement('label'),input=document.createElement('input');label.textContent=key;input.type=key==='enabled'?'checkbox':'number';input.step='.01';if(key==='enabled')input.checked=effect[key];else input.value=effect[key];input.onchange=e=>{e.stopPropagation();editor.stopPreview();editor.edit(d=>{d.buses.find(b=>b.id===bus.id).effects[index][key]=key==='enabled'?input.checked:Number(input.value);});};label.append(input);row.append(label);}row.append(button('위로',b=>{if(index)[b.effects[index-1],b.effects[index]]=[b.effects[index],b.effects[index-1]];}),button('삭제',b=>b.effects.splice(index,1)));section.append(row);}
  for(const type of Object.keys(dspDefaults))section.append(button(type+' 추가',b=>{b.effects??=[];b.effects.push({type,enabled:true,...dspDefaults[type]});}));const sends=document.createElement('h3');sends.textContent='Send / Return';section.append(sends);for(const [index,send] of (bus.sends||[]).entries()){const row=document.createElement('label');row.textContent=send.bus;const input=document.createElement('input');input.type='number';input.value=send.level;input.onchange=e=>{e.stopPropagation();editor.stopPreview();editor.edit(d=>d.buses.find(b=>b.id===bus.id).sends[index].level=Number(input.value));};row.append(input,button('삭제',b=>b.sends.splice(index,1)));section.append(row);}const target=document.createElement('select');for(const b of editor.doc.data.buses.filter(b=>b.id!==bus.id)){const o=document.createElement('option');o.value=b.id;o.textContent=b.name;target.append(o);}section.append(target,button('Send 추가',b=>{b.sends??=[];b.sends.push({bus:target.value,level:-12,preFader:false});}));renderDucking(editor,bus,section);editor.element.querySelector('.mixer-details').append(section);
}
